# Let's try a programmatic approach - write a small C# program to read the binlog
mkdir -p /tmp/binlog-reader && cd /tmp/binlog-reader && cat > Program.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var build = BinaryLog.ReadBuild("/tmp/sv-f71bc5aa8b31490badce543ad21cc9fe/build.binlog");

var errors = new List<(string project, string code, string message, string file, int line)>();
var warnings = new List<(string project, string code, string message, string file, int line)>();

build.VisitAllChildren<Error>(e => {
    var proj = "";
    var node = e.Parent;
    while (node != null) {
        if (node is Project p) { proj = p.Name; break; }
        node = node.Parent;
    }
    errors.Add((proj, e.Code ?? "", e.Text ?? "", e.File ?? "", e.LineNumber));
});

build.VisitAllChildren<Warning>(w => {
    var proj = "";
    var node = w.Parent;
    while (node != null) {
        if (node is Project p) { proj = p.Name; break; }
        node = node.Parent;
    }
    warnings.Add((proj, w.Code ?? "", w.Text ?? "", w.File ?? "", w.LineNumber));
});

Console.WriteLine($"=== BUILD ERRORS ({errors.Count}) ===");
foreach (var g in errors.GroupBy(e => e.project))
{
    Console.WriteLine($"\n--- Project: {g.Key} ---");
    foreach (var e in g)
    {
        Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.message}");
    }
}

Console.WriteLine($"\n=== BUILD WARNINGS ({warnings.Count}) ===");
foreach (var g in warnings.GroupBy(w => w.project).Take(10))
{
    Console.WriteLine($"\n--- Project: {g.Key} ---");
    foreach (var w in g.Take(5))
    {
        Console.WriteLine($"  [{w.code}] {w.file}({w.line}): {w.message}");
    }
    if (g.Count() > 5) Console.WriteLine($"  ... and {g.Count() - 5} more warnings");
}

// Also show project dependency info - which projects failed
Console.WriteLine("\n=== FAILED PROJECTS ===");
build.VisitAllChildren<Project>(p => {
    if (!p.Succeeded)
        Console.WriteLine($"  FAILED: {p.Name} (TargetFramework: {p.TargetFramework})");
});
EOF

